# ---------------------------------------------------------------- terminal capabilities
tp_ui_init() {
  TP_COLOR=0; TP_UNICODE=1; TP_COLS=80
  if [ -t 1 ] && [ "${TERM:-dumb}" != "dumb" ]; then TP_COLOR=1; fi
  if [ -n "${FORCE_COLOR:-}" ] && [ "${FORCE_COLOR}" != "0" ]; then TP_COLOR=1; fi
  if [ -n "${NO_COLOR:-}" ] || [ "${FORCE_COLOR:-}" = "0" ]; then TP_COLOR=0; fi
  local loc="${LC_ALL:-}${LC_CTYPE:-}${LANG:-}"
  if [ "${BRAND_ASCII:-}" = "1" ] || [ "${BRAND_ASCII:-}" = "true" ]; then TP_UNICODE=0
  elif [ -n "$loc" ]; then case "$loc" in *[Uu][Tt][Ff]-8*|*[Uu][Tt][Ff]8*) ;; *) TP_UNICODE=0 ;; esac
  fi
  if [ "${TERM:-}" = "linux" ] || [ "${TERM:-}" = "dumb" ]; then
    case "$loc" in *[Uu][Tt][Ff]-8*|*[Uu][Tt][Ff]8*) ;; *) TP_UNICODE=0 ;; esac
  fi
  local c=""
  if [ -t 1 ] && command -v tput >/dev/null 2>&1; then c=$(tput cols 2>/dev/null || true); fi
  [ -z "$c" ] && c="${COLUMNS:-}"
  case "$c" in ''|*[!0-9]*) c=80 ;; esac
  TP_COLS=$c
}

# tp_paint <256-colour> <text...>   (cyan=45 blue=33 violet=99 white=15 green=41)
tp_paint() {
  local code="$1"; shift
  if [ "$TP_COLOR" = 1 ]; then printf '\033[1;38;5;%sm%s\033[0m\n' "$code" "$*"; else printf '%s\n' "$*"; fi
}

tp_logo() {
  if [ "$TP_COLS" -lt "$TP_LOGO_WIDTH" ]; then
    if [ "$TP_UNICODE" = 1 ]; then tp_paint 45 "◈ TANVEER PRIME ◈"; else tp_paint 45 "* TANVEER PRIME *"; fi
    return
  fi
  local i=0 line colr
  while IFS= read -r line; do
    case $i in 0|1) colr=45 ;; 2|3) colr=33 ;; *) colr=99 ;; esac
    tp_paint "$colr" "$line"; i=$((i + 1))
  done < <(tp_logo_lines)
}

tp_panel() {
  if [ "$TP_COLS" -lt "$TP_PANEL_WIDTH" ]; then
    local d='◈'; [ "$TP_UNICODE" = 1 ] || d='*'
    tp_paint 45 "$d T A N V E E R   P R I M E $d"
    tp_paint 15 "[ CREATOR ] MADE BY TANVEER"
    tp_paint 45 "[ DISCORD ] tanveer5637"
    return
  fi
  local line; while IFS= read -r line; do tp_paint 33 "$line"; done < <(tp_panel_lines)
}

tp_signature() {
  local s="$TP_ATTRIBUTION"; [ "$TP_COLS" -lt $((${#s} + 2)) ] && s="$TP_SIGNATURE"
  tp_paint 99 "$s"
}

tp_banner_full() { echo; tp_logo; echo; tp_panel; echo; }
tp_banner_compact() {
  local title="${1:-TANVEER PRIME}" d='◈' bar='━'
  [ "$TP_UNICODE" = 1 ] || { d='*'; bar='-'; }
  local n=$((TP_COLS - 2)); [ "$n" -gt 48 ] && n=48; [ "$n" -lt 10 ] && n=10
  local line; line=$(printf '%*s' "$n" '' | tr ' ' "$bar")
  echo; tp_paint 45 "$d T A N V E E R   P R I M E $d"; tp_paint 99 "$line"; tp_paint 15 "$title"; tp_signature; echo
}

# ---------------------------------------------------------------- messages (green only for confirmed success)
tp_info() { if [ "$TP_COLOR" = 1 ]; then printf '\033[38;5;45m◈\033[0m %s\n' "$*"; else printf '[i] %s\n' "$*"; fi; }
tp_ok()   { if [ "$TP_COLOR" = 1 ]; then printf '\033[1;38;5;41m✔\033[0m %s\n' "$*"; else printf '[ok] %s\n' "$*"; fi; }
tp_warn() { if [ "$TP_COLOR" = 1 ]; then printf '\033[38;5;99m!\033[0m %s\n' "$*" >&2; else printf '[!] %s\n' "$*" >&2; fi; }
tp_err()  { if [ "$TP_COLOR" = 1 ]; then printf '\033[1;38;5;15m✘ %s\033[0m\n' "$*" >&2; else printf '[x] %s\n' "$*" >&2; fi; }
tp_step() { echo; if [ "$TP_COLOR" = 1 ]; then printf '\033[1;38;5;33m━━ %s\033[0m\n' "$*"; else printf '== %s ==\n' "$*"; fi; }
tp_die()  { tp_err "$*"; exit 1; }

# ---------------------------------------------------------------- helpers
tp_have() { command -v "$1" >/dev/null 2>&1; }

# tp_env_get <file> <KEY>: read one value from an env file without sourcing it (no code execution).
tp_env_get() {
  local file="$1" key="$2" line val
  [ -r "$file" ] || return 1
  line=$(grep -E "^${key}=" "$file" | tail -n 1) || return 1
  val="${line#*=}"
  case "$val" in \"*\") val="${val#\"}"; val="${val%\"}"; val="${val//\\\"/\"}"; val="${val//\\\\/\\}" ;; esac
  printf '%s' "$val"
}

# tp_wait_connected <service> <seconds> <since-timestamp>
#   0 = bot logged "connected to Discord"; 1 = service stopped/failed; 2 = still starting after the timeout
tp_wait_connected() {
  local svc="$1" limit="$2" since="$3" i=0
  while [ "$i" -lt "$limit" ]; do
    if ! systemctl is-active --quiet "$svc"; then
      # "activating (auto-restart)" counts as failed for our purposes
      sleep 1; systemctl is-active --quiet "$svc" || return 1
    fi
    if journalctl -u "$svc" --since "$since" --no-pager -o cat 2>/dev/null | grep -q 'connected to Discord'; then return 0; fi
    sleep 2; i=$((i + 2))
  done
  return 2
}

tp_log_tail() { journalctl -u "$1" -n "${2:-25}" --no-pager -o cat 2>/dev/null | sed 's/^/    /' || true; }

tp_require_root() {
  [ "${TP_ALLOW_NON_ROOT:-}" = "1" ] && return 0
  [ "$(id -u)" -eq 0 ] || tp_die "This must run as root. Use: curl -fsSL <url> | sudo bash   (or run the script with sudo)"
}

tp_tty_ok() { { : </dev/tty >/dev/tty; } 2>/dev/null; }
